{"content": """"
多管线并行处理引擎
每条管线使用不同策略，选评分最低的结果
"""
import re
import random
import json
import os

class Pipeline:
    def __init__(self, name):
        self.name = name

    def process(self, text):
        return text

class PipelineA(Pipeline):
    """学术模板替换管线"""
    def __init__(self):
        super().__init__('学术模板替换')
        self.rules = self._load_rules()

    def _load_rules(self):
        rules_file = os.path.join(os.path.dirname(__file__), 'rules', 'replacement_rules.json')
        with open(rules_file, 'r', encoding='utf-8') as f:
            return json.load(f)

    def process(self, text):
        random.seed(42)
        # 学术模板替换
        for old, options in self.rules.get('academic_templates', {}).items():
            if old not in text: continue
            replacement = random.choice(options)
            text = text.replace(old, replacement)

        # 连接词替换
        for old, options in self.rules.get('connectors', {}).items():
            if old not in text: continue
            replacement = random.choice(options)
            text = text.replace(old, replacement)

        return text

class PipelineB(Pipeline):
    """对抗统计替换管线"""
    def __init__(self):
        super().__init__('对抗统计替换')
        self.rules = self._load_rules()

    def _load_rules(self):
        rules_file = os.path.join(os.path.dirname(__file__), 'rules', 'replacement_rules.json')
        with open(rules_file, 'r', encoding='utf-8') as f:
            return json.load(f)

    def process(self, text):
        random.seed(99)

        # 通用词替换（随机选80-100%的位置替换）
        common = self.rules.get('common_words', {})
        for word, options in common.items():
            if word not in text: continue
            positions = [m.start() for m in re.finditer(re.escape(word), text)]
            if not positions: continue

            if isinstance(options, list):
                ratio = random.uniform(0.6, 1.0)
            else:
                options = [options]
                ratio = 0.7

            n = max(1, int(len(positions) * ratio))
            selected = random.sample(positions, min(n, len(positions)))
            for pos in sorted(selected, reverse=True):
                replacement = random.choice(options)
                text = text[:pos] + replacement + text[pos+len(word):]

        # 字符级随机替换（改统计分布）
        char_swaps = {
            '的': ['的', '之'], '和': ['和', '与', '跟'], 
            '但': ['但', '不过', '然而'], '也': ['也', '亦'],
            '从': ['从', '自'], '很': ['很', '非常', '相当'],
        }
        for char, options in char_swaps.items():
            if char not in text: continue
            positions = [m.start() for m in re.finditer(re.escape(char), text)]
            if not positions: continue
            n = max(1, int(len(positions) * 0.3))
            selected = random.sample(positions, min(n, len(positions)))
            for pos in sorted(selected, reverse=True):
                text = text[:pos] + random.choice(options) + text[pos+1:]

        return text

class PipelineC(Pipeline):
    """句法重构管线"""
    def __init__(self):
        super().__init__('句法重构')

    def process(self, text):
        random.seed(77)

        # 替换句号-逗号比例
        # 部分句号改分号或逗号
        text = re.sub(r'([^。！？]{5,15})。([^。！？]{10,30})。', 
                      lambda m: m.group(1)+'，'+m.group(2)+'。', text, count=15)
        text = re.sub(r'([^。！？]{8,20})。([^。！？]{8,20})。',
                      lambda m: m.group(1)+'；'+m.group(2)+'。', text, count=10)

        # 删除AI模板句
        delete_phrases = [
            '综上所述', '总而言之', '由此可见', '不难发现',
            '毫无疑问', '显而易见', '不可否认', '毋庸置疑',
            '众所周知', '不言而喻', '需要指出的是',
        ]
        for phrase in delete_phrases:
            if phrase in text:
                text = text.replace(phrase, '')

        # 简化绝对化表达
        absolutes = {
            '必然': '很可能', '一定会': '较大可能会', 
            '必将': '有望', '绝对': '在很大程度',
            '无一例外': '在绝大多数情况下',
            '完全': '相当程度',
        }
        for old, new in absolutes.items():
            if old in text:
                text = text.replace(old, new)

        return text

class PipelineD(Pipeline):
    """组合管线 — A+B+C顺序执行"""
    def __init__(self):
        super().__init__('组合管线')
        self.pipelines = [PipelineA(), PipelineB(), PipelineC()]

    def process(self, text):
        for p in self.pipelines:
            text = p.process(text)
        return text


def run_all_pipelines(text):
    """运行所有管线返回结果列表"""
    pipelines = [PipelineA(), PipelineB(), PipelineC(), PipelineD()]
    results = []
    for p in pipelines:
        result = p.process(text)
        results.append((p.name, result))
    return results

if __name__ == '__main__':
    path = r'C:\Users\27063\Desktop\工具箱\论文降低aigc分析文献库\全球治理视域下的变局与共识_v3（v9.1策略）.txt'
    with open(path, 'r', encoding='utf-8') as f:
        text = f.read()

    results = run_all_pipelines(text)
    for name, result in results:
        cn = len(re.findall(r'[\u4e00-\u9fff]', result))
        print(f'{name}: {cn}字')
